import {TIVA_BOARD} from './tiva-board.js';
import {crc32} from './project-zip.js';
export function packTivaImage(bytes){const out=new Uint8Array(80+bytes.length),v=new DataView(out.buffer);out.set(new TextEncoder().encode('CFTIVA1\0'));out.set(new TextEncoder().encode(TIVA_BOARD.id),8);v.setUint32(64,bytes.length,true);v.setUint32(68,crc32(bytes),true);out.set(bytes,80);validateTivaImage(out);return out;}
export function validateTivaImage(image){if(!(image instanceof Uint8Array)||image.length<88)throw Error('Tiva firmware başlığı geçersiz.');const v=new DataView(image.buffer,image.byteOffset,image.byteLength),dec=new TextDecoder(),bytes=image.subarray(80);if(dec.decode(image.subarray(0,8))!=='CFTIVA1\0'||dec.decode(image.subarray(8,64)).replace(/\0.*$/s,'')!==TIVA_BOARD.id||image.subarray(72,80).some(x=>x)||v.getUint32(64,true)!==bytes.length||bytes.length>TIVA_BOARD.flashSize||v.getUint32(68,true)!==crc32(bytes))throw Error('Tiva firmware hedefi/boyutu/checksum geçersiz.');const sp=v.getUint32(80,true),pc=v.getUint32(84,true);if(sp!==0x20008000||!(pc&1)||pc<8||pc>=bytes.length)throw Error('Tiva reset vektörü geçersiz.');return bytes;}
